#!/usr/bin/env python3
from pathlib import Path
p=Path("index.html")
html=p.read_text(encoding="utf-8")
needle="            map2RetireLegacyRoadVisuals();\n\n            // MAP2-18: only after all authored gates and original physical solids"
block="            // MAP2-28: turn the longest real Map4 building chains into authored\n            // architectural chicanes. The established MAP2-19 building-road groups\n            // remain the authoritative backbone; we relocate whole real complexes,\n            // then propagate the same smooth displacement into every through-building\n            // and bridge module between them. No placeholder road/building is created.\n            const map2AuthorArchitecturalChicaneChains=()=>{\n                const route=window.starbladeMap2ThroughRoute;\n                const chains=window.starbladeMap2LongBuildingChains;\n                const road=window.starbladeMap2BuildingRoad;\n                if(!route?.modules?.length||!chains?.chains?.length||!road?.groups?.length||!road?.knots?.length)return null;\n\n                const roots=map2ExactBuildingRoots();\n                const rootByName=new Map(roots.map(r=>[r.name,r]));\n                const selectedChains=chains.chains\n                    .filter(c=>c.span>=10000)\n                    .slice(0,6);\n                const movedRootNames=new Set();\n                const movedModuleIds=new Set();\n                const groupShiftByRoot=new Map();\n                const chainShiftRows=[];\n                const moved=[];\n                const chainRows=[];\n                let maxLateralShift=0,maxVerticalShift=0;\n\n                const gateClearance=d=>map2Gates.length\n                    ?Math.min(...map2Gates.map(g=>Math.abs(g.distance-d)))\n                    :99999;\n                const techEdgeClearance=d=>{\n                    const seg=MAP2_SEGMENTS.find(s=>\n                        s.kind==='TECH'&&d>=s.from*MAP2_DISTANCE&&d<=s.to*MAP2_DISTANCE\n                    );\n                    if(!seg)return 0;\n                    return Math.min(d-seg.from*MAP2_DISTANCE,seg.to*MAP2_DISTANCE-d);\n                };\n                const shiftPoint=(p,dx,dy)=>{\n                    if(!p)return;\n                    p.x+=dx;p.y+=dy;\n                };\n                const clampTarget=(desired,base,prev,continuity,maxMove,lo,hi)=>{\n                    let min=Math.max(lo,base-maxMove);\n                    let max=Math.min(hi,base+maxMove);\n                    if(Number.isFinite(prev)){\n                        min=Math.max(min,prev-continuity);\n                        max=Math.min(max,prev+continuity);\n                    }\n                    if(min>max){\n                        const fallback=Number.isFinite(prev)\n                            ?THREE.MathUtils.clamp(base,prev-continuity,prev+continuity)\n                            :base;\n                        return THREE.MathUtils.clamp(fallback,lo,hi);\n                    }\n                    return THREE.MathUtils.clamp(desired,min,max);\n                };\n\n                // 1) Author a continuous macro path on the existing real building\n                // groups. Adjacent groups inside 2.5 km are explicitly constrained to\n                // <=66 lateral / <=51 vertical separation, preserving MAP2-25 handoffs.\n                selectedChains.forEach((chain,chainIndex)=>{\n                    const groups=(road.groups||[])\n                        .filter(g=>g.open&&g.d>=chain.from&&g.d<=chain.to&&map2Segment(g.d).kind==='TECH')\n                        .sort((a,b)=>a.d-b.d);\n                    if(groups.length<2)return;\n\n                    let prev=null;\n                    const shifts=[];\n                    for(let i=0;i<groups.length;i++){\n                        const g=groups[i];\n                        const t=groups.length<=1?.5:i/(groups.length-1);\n                        const edgeEnvelope=Math.pow(Math.max(0,Math.sin(Math.PI*t)),.78);\n                        const gateBlend=THREE.MathUtils.clamp((gateClearance(g.d)-180)/520,0,1);\n                        const techBlend=THREE.MathUtils.clamp((techEdgeClearance(g.d)-120)/620,0,1);\n                        const envelope=(i===0||i===groups.length-1)?0:edgeEnvelope*gateBlend*techBlend;\n\n                        const phase=chainIndex*.173;\n                        const desiredX=THREE.MathUtils.lerp(\n                            g.x,\n                            178*Math.sin((t*2.25+phase)*Math.PI*2),\n                            envelope*.86\n                        );\n                        const desiredY=THREE.MathUtils.lerp(\n                            g.y,\n                            -68+72*Math.sin((t*2.70+phase*.73)*Math.PI*2),\n                            envelope*.76\n                        );\n                        const linked=prev&&g.d-prev.d<=2500;\n                        const targetX=clampTarget(\n                            desiredX,g.x,linked?prev.x:NaN,66,145,-220,220\n                        );\n                        const targetY=clampTarget(\n                            desiredY,g.y,linked?prev.y:NaN,51,64,-170,85\n                        );\n                        const dx=targetX-g.x,dy=targetY-g.y;\n\n                        const groupRoots=(g.rootNames||[]).map(n=>rootByName.get(n)).filter(Boolean);\n                        if(groupRoots.length&&(Math.abs(dx)>1||Math.abs(dy)>1)){\n                            map2MoveRouteBuildingGroup(groupRoots,g.d,dx,dy);\n                            for(const r of groupRoots){\n                                movedRootNames.add(r.name);\n                                groupShiftByRoot.set(r.name,{dx,dy,d:g.d,chainIndex});\n                                r.userData.map2ArchitecturalChicane=true;\n                                r.userData.map2ArchitecturalChicaneChain=chainIndex;\n                                r.userData.map2ArchitecturalChicaneShiftX=dx;\n                                r.userData.map2ArchitecturalChicaneShiftY=dy;\n                                if(Number.isFinite(r.userData.map2SequenceLaneX))r.userData.map2SequenceLaneX+=dx;\n                                if(Number.isFinite(r.userData.map2SequenceLaneY))r.userData.map2SequenceLaneY+=dy;\n                            }\n                        }else{\n                            for(const r of groupRoots)groupShiftByRoot.set(r.name,{dx,dy,d:g.d,chainIndex});\n                        }\n\n                        g.x=targetX;g.y=targetY;\n                        g.map2ArchitecturalChicane=true;\n                        g.chicaneChain=chainIndex;\n\n                        // The centre building knot is the MAP2-19 authoritative\n                        // passage and must move exactly with the real complex.\n                        for(const k of road.knots){\n                            if(k.source==='THROUGH_BUILDING')continue;\n                            if(Math.abs(k.distance-g.d)>1)continue;\n                            k.x=targetX;k.y=targetY;\n                            k.map2ArchitecturalChicane=true;\n                            k.chicaneChain=chainIndex;\n                        }\n\n                        shifts.push({d:g.d,dx,dy,x:targetX,y:targetY});\n                        prev={d:g.d,x:targetX,y:targetY};\n                        maxLateralShift=Math.max(maxLateralShift,Math.abs(dx));\n                        maxVerticalShift=Math.max(maxVerticalShift,Math.abs(dy));\n                    }\n                    chainShiftRows.push({chainIndex,from:chain.from,to:chain.to,span:chain.span,shifts});\n                });\n\n                const interpolatedShiftAt=(d,chainRow)=>{\n                    const s=chainRow?.shifts||[];\n                    if(!s.length)return {dx:0,dy:0};\n                    if(d<=s[0].d)return {dx:s[0].dx,dy:s[0].dy};\n                    if(d>=s[s.length-1].d)return {dx:s[s.length-1].dx,dy:s[s.length-1].dy};\n                    let lo=0,hi=s.length-1;\n                    while(lo+1<hi){\n                        const mid=(lo+hi)>>1;\n                        if(s[mid].d<=d)lo=mid;else hi=mid;\n                    }\n                    const a=s[lo],b=s[hi];\n                    const t=THREE.MathUtils.clamp((d-a.d)/Math.max(1,b.d-a.d),0,1);\n                    return {\n                        dx:THREE.MathUtils.lerp(a.dx,b.dx,t),\n                        dy:THREE.MathUtils.lerp(a.dy,b.dy,t)\n                    };\n                };\n\n                // 2) Propagate the macro displacement into every through-building\n                // module. Base modules inherit their own complex shift; inserted exact\n                // bridge modules interpolate between neighbouring real complexes.\n                const modules=route.modules.slice().sort((a,b)=>a.centerDistance-b.centerDistance);\n                for(const module of modules){\n                    const chainRow=chainShiftRows.find(c=>module.centerDistance>=c.from&&module.centerDistance<=c.to);\n                    if(!chainRow)continue;\n\n                    const direct=(module.rootNames||[])\n                        .map(n=>groupShiftByRoot.get(n))\n                        .filter(Boolean);\n                    let dx,dy;\n                    if(direct.length){\n                        dx=direct.reduce((n,q)=>n+q.dx,0)/direct.length;\n                        dy=direct.reduce((n,q)=>n+q.dy,0)/direct.length;\n                    }else{\n                        ({dx,dy}=interpolatedShiftAt(module.centerDistance,chainRow));\n                    }\n                    if(Math.abs(dx)<1&&Math.abs(dy)<1)continue;\n\n                    const moduleRoots=(module.rootNames||[]).map(n=>rootByName.get(n)).filter(Boolean);\n                    const rootsToMove=moduleRoots.filter(r=>!movedRootNames.has(r.name));\n                    if(rootsToMove.length){\n                        map2MoveRouteBuildingGroup(rootsToMove,module.centerDistance,dx,dy);\n                        for(const r of rootsToMove){\n                            movedRootNames.add(r.name);\n                            r.userData.map2ArchitecturalChicane=true;\n                            r.userData.map2ArchitecturalChicaneChain=chainRow.chainIndex;\n                            r.userData.map2ArchitecturalChicaneShiftX=dx;\n                            r.userData.map2ArchitecturalChicaneShiftY=dy;\n                            if(Number.isFinite(r.userData.map2SequenceLaneX))r.userData.map2SequenceLaneX+=dx;\n                            if(Number.isFinite(r.userData.map2SequenceLaneY))r.userData.map2SequenceLaneY+=dy;\n                        }\n                    }\n\n                    shiftPoint(module.entrance,dx,dy);\n                    shiftPoint(module.core,dx,dy);\n                    shiftPoint(module.exit,dx,dy);\n                    module.points.forEach(p=>shiftPoint(p,dx,dy));\n                    module.chicane=true;\n                    module.chicaneChain=chainRow.chainIndex;\n                    module.chicaneShiftX=dx;\n                    module.chicaneShiftY=dy;\n                    movedModuleIds.add(module.id);\n\n                    for(const k of road.knots){\n                        if(k.moduleId!==module.id)continue;\n                        k.x+=dx;k.y+=dy;\n                        k.map2ArchitecturalChicane=true;\n                        k.chicaneChain=chainRow.chainIndex;\n                    }\n                    for(const k of route.moduleAnchors){\n                        if(k.moduleId!==module.id)continue;\n                        k.x+=dx;k.y+=dy;\n                        k.map2ArchitecturalChicane=true;\n                        k.chicaneChain=chainRow.chainIndex;\n                    }\n\n                    maxLateralShift=Math.max(maxLateralShift,Math.abs(dx));\n                    maxVerticalShift=Math.max(maxVerticalShift,Math.abs(dy));\n                    moved.push({\n                        id:module.id,chainIndex:chainRow.chainIndex,d:module.centerDistance,\n                        dx,dy,x:module.core.x,y:module.core.y,\n                        roots:moduleRoots.map(r=>r.name)\n                    });\n                }\n\n                // 3) Summarize the actual flown module path after all moves.\n                for(const chainRow of chainShiftRows){\n                    const mm=moved.filter(m=>m.chainIndex===chainRow.chainIndex).sort((a,b)=>a.d-b.d);\n                    if(!mm.length)continue;\n                    let priorSign=0,directionChanges=0,left=0,right=0;\n                    for(const m of mm){\n                        const sign=m.x<-55?-1:m.x>55?1:0;\n                        if(sign<0)left++;\n                        if(sign>0)right++;\n                        if(sign&&priorSign&&sign!==priorSign)directionChanges++;\n                        if(sign)priorSign=sign;\n                    }\n                    chainRows.push({\n                        chainIndex:chainRow.chainIndex,from:chainRow.from,to:chainRow.to,span:chainRow.span,\n                        candidates:mm.length,moved:mm.length,left,right,directionChanges,\n                        firstMoved:mm[0].d,lastMoved:mm[mm.length-1].d\n                    });\n                }\n\n                road.knots.sort((a,b)=>a.distance-b.distance);\n                route.routeAnchors=road.knots;\n                road.map2ArchitecturalChicaneFlow=true;\n                route.map2ArchitecturalChicaneFlow=true;\n\n                const summary={\n                    philosophy:'REAL_MAP4_BUILDINGS_FORM_LONG_CHICANES',\n                    selectedChains:selectedChains.length,\n                    activeChains:chainRows.length,\n                    movedModules:movedModuleIds.size,\n                    movedRoots:movedRootNames.size,\n                    maxLateralShift,maxVerticalShift,\n                    leftModules:moved.filter(m=>m.x<-55).length,\n                    rightModules:moved.filter(m=>m.x>55).length,\n                    directionChanges:chainRows.reduce((n,r)=>n+r.directionChanges,0),\n                    longestMovedSpan:chainRows.reduce((mx,r)=>\n                        Math.max(mx,(r.lastMoved??r.from)-(r.firstMoved??r.from)),0),\n                    chains:chainRows,\n                    moved\n                };\n                window.starbladeMap2ArchitecturalChicanes=summary;\n                Object.assign(map2VisualStageStats,{\n                    architecturalChicaneChains:summary.activeChains,\n                    architecturalChicaneModules:summary.movedModules,\n                    architecturalChicaneRoots:summary.movedRoots,\n                    architecturalChicaneMaxLateralShift:summary.maxLateralShift,\n                    architecturalChicaneMaxVerticalShift:summary.maxVerticalShift,\n                    architecturalChicaneDirectionChanges:summary.directionChanges,\n                    architecturalChicaneLongestSpan:summary.longestMovedSpan\n                });\n                return summary;\n            };\n            map2AuthorArchitecturalChicaneChains();\n\n"
if "map2AuthorArchitecturalChicaneChains" in html:
    print("MAP2-28 already applied")
    raise SystemExit(0)
if html.count(needle)!=1:
    raise SystemExit(f"MAP2-28 anchor count expected 1, got {html.count(needle)}")
html=html.replace(needle, "            map2RetireLegacyRoadVisuals();\n\n"+block+"            // MAP2-18: only after all authored gates and original physical solids")
p.write_text(html,encoding="utf-8")
print("Applied MAP2-28 continuous group-and-bridge architectural chicane warp")
